import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.2; // Meters (Alignment guide activation radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    guides?: THREE.Vector3[][];
}

// --- Geometry Helpers (Cutting Logic) ---

// Check if point C is on segment AB
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false; // Not collinear

    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false; // Before a

    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false; // After b

    return true;
};

// Find which edge index of the polygon the point lies on
const findEdgeIndex = (poly: IPoint[], p: IPoint): number => {
    for (let i = 0; i < poly.length; i++) {
        const p1 = poly[i];
        const p2 = poly[(i + 1) % poly.length];
        if (isPointOnSegment(p, p1, p2)) return i;
    }
    return -1;
};

// Split a shape by a polyline that starts and ends on the shape's boundary
const splitShapeByPolyline = (shape: IShape, polyline: IPoint[]): IShape[] | null => {
    const poly = shape.points;
    if (polyline.length < 2) return null;

    const startP = polyline[0];
    const endP = polyline[polyline.length - 1];

    const idxA = findEdgeIndex(poly, startP);
    const idxB = findEdgeIndex(poly, endP);

    if (idxA === -1 || idxB === -1) return null;

    // Helper to extract loop
    // Polygon 1: StartP -> ... polyline ... -> EndP -> Shape[idxB+1] ... -> Shape[idxA] -> StartP
    // But we need to be careful with direction and indices.

    // Construct new Polygon 1
    // Follow shape from idxA next to idxB, then connect via reversed polyline
    const newPoly1: IPoint[] = [startP];

    // Add polyline points (excluding start, including end)
    for (let i = 1; i < polyline.length; i++) {
        newPoly1.push(polyline[i]);
    }

    // From EndP (which is polyline[last]), traverse shape boundary until StartP
    // EndP is on edge idxB (between poly[idxB] and poly[idxB+1])
    // So next vertex is poly[idxB+1]
    let curr = (idxB + 1) % poly.length;
    while (curr !== (idxA + 1) % poly.length) {
        newPoly1.push(poly[curr]);
        curr = (curr + 1) % poly.length;
    }
    // Finally close with StartP (implicit or explicit)
    // isPointOnSegment checks if it lies ON the segment.
    // If startP is exactly poly[idxA+1], we might duplicate points, but that's usually fine for rendering.

    // Construct new Polygon 2
    // Follow shape from idxB next to idxA, then connect via polyline
    const newPoly2: IPoint[] = [endP];

    // Add reversed polyline (excluding end, including start)
    for (let i = polyline.length - 2; i >= 0; i--) {
        newPoly2.push(polyline[i]);
    }

    // From StartP, traverse shape boundary until EndP
    // StartP is on edge idxA. Next vertex is poly[idxA+1]
    curr = (idxA + 1) % poly.length;
    while (curr !== (idxB + 1) % poly.length) {
        newPoly2.push(poly[curr]);
        curr = (curr + 1) % poly.length;
    }

    // Helper to center and create shape
    const makeShape = (pts: IPoint[], suffix: string): IShape => {
        // Remove duplicates/close loop
        const uniquePts = pts.filter((p, i) => {
             const next = pts[(i+1)%pts.length];
             return Math.abs(p.x - next.x) > EPSILON || Math.abs(p.z - next.z) > EPSILON;
        });

        if (uniquePts.length < 3) return shape; // Fail safe

        const cx = uniquePts.reduce((s, p) => s + p.x, 0) / uniquePts.length;
        const cz = uniquePts.reduce((s, p) => s + p.z, 0) / uniquePts.length;

        const localPts = uniquePts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
        localPts.push(localPts[0]); // Ensure closed

        return {
            ...shape,
            id: `${shape.id}-${suffix}`,
            position: [cx, shape.position[1], cz],
            points: localPts,
            rotation: 0, // Reset rotation since points are world-aligned
            scale: [1, 1, 1]
        };
    };

    return [makeShape(newPoly1, 'cut1'), makeShape(newPoly2, 'cut2')];
};

// Calculate Polygon Area (for validation)
const calculatePolygonArea = (points: IPoint[]) => {
    let area = 0;
    for (let i = 0; i < points.length; i++) {
        const j = (i + 1) % points.length;
        area += points[i].x * points[j].z;
        area -= points[i].z * points[j].x;
    }
    return Math.abs(area / 2);
};

// --- Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const getBaseDimensions = (points: IPoint[]) => {
    if (!points || points.length === 0) return { width: 0, depth: 0, minX: 0, maxX: 0, minZ: 0, maxZ: 0, centerX: 0, centerZ: 0 };
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        minX = Math.min(minX, p.x);
        maxX = Math.max(maxX, p.x);
        minZ = Math.min(minZ, p.z);
        maxZ = Math.max(maxZ, p.z);
    });
    return { 
        width: maxX - minX || 0.1, 
        depth: maxZ - minZ || 0.1,
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2
    };
};

// Transform a local point to world space based on shape props
const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    // Scale
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    // Rotate (around Y axis)
    // x' = x*cos - z*sin
    // z' = x*sin + z*cos
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    // Translate
    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

// Project point onto line segment [v, w]
const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const l2 = v.distanceToSquared(w);
  if (l2 === 0) return v;
  let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(
    v.x + t * (w.x - v.x),
    v.y, // Keep height consistent for now
    v.z + t * (w.z - v.z)
  );
};

// --- Geometry Snapping Logic (Adsorption & Alignment) ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    // 0. Check Active Points (Priority: High)
    if (activePoints && activePoints.length > 0) {
        for (const p of activePoints) {
             const pt = new THREE.Vector3(p.x, p.y, p.z);
             const dist = pt.distanceTo(cursorPos);
             if (dist < threshold && dist < bestSnap.distance) {
                 bestSnap = {
                     position: pt,
                     type: 'vertex',
                     distance: dist
                 };
             }
        }
    }

    // 1. Check Existing Shapes Vertices (Priority: High)
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            const dist = worldPt.distanceTo(cursorPos);

            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = {
                    position: worldPt,
                    type: 'vertex',
                    distance: dist,
                    snapObjectId: shape.id
                };
            }
        }
    }

    if (bestSnap.type === 'vertex') return bestSnap;

    // 2. Check Edges & Midpoints (Priority: Medium)
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;

        const pts = shape.points;
        const len = pts.length;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);

             // Midpoint check
             const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
             const distMid = mid.distanceTo(cursorPos);

             if (distMid < threshold && distMid < minEdgeDist) {
                 bestEdgeSnap = {
                     position: mid,
                     type: 'midpoint',
                     distance: distMid,
                     snapObjectId: shape.id
                 };
                 minEdgeDist = distMid;
                 continue; // Found a midpoint closer than edge, optimize
             }

             // Edge Projection check (Fitting against the edge)
             const projected = closestPointOnSegment(cursorPos, p1, p2);
             const distEdge = projected.distanceTo(cursorPos);

             if (distEdge < threshold && distEdge < minEdgeDist) {
                 bestEdgeSnap = {
                     position: projected,
                     type: 'edge',
                     distance: distEdge,
                     snapObjectId: shape.id
                 };
                 minEdgeDist = distEdge;
             }
        }
    }

    if (bestEdgeSnap) return bestEdgeSnap;

    // 3. Smart Alignment Guides (Priority: Low)
    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;

    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       s.points.forEach(p => candidates.push(transformPoint(p, s)));
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));

    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) {
            minDiffX = diffX;
            alignX = pt.x;
            guideXSrc = pt;
        }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) {
            minDiffZ = diffZ;
            alignZ = pt.z;
            guideZSrc = pt;
        }
    }

    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;

        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) {
            guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        }
        if (alignZ !== null && guideZSrc) {
            guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        }

        return {
            position: snappedPos,
            type: 'align',
            distance: 0,
            guides
        };
    }

    return bestSnap;
};

// --- Components ---

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();

    useEffect(() => {
        if (!view) return;
        const ctrl = controls as unknown as OrbitControlsImpl;
        if (!ctrl) return;
        const currentTarget = ctrl.target.clone();
        const dist = camera.position.distanceTo(currentTarget) || 10;
        const offset = 0.001; 
        switch (view) {
            case '上視圖': camera.position.set(currentTarget.x, currentTarget.y + dist, currentTarget.z + offset); break;
            case '下視圖': camera.position.set(currentTarget.x, currentTarget.y - dist, currentTarget.z + offset); break;
            case '前視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z + dist); break;
            case '後視圖': camera.position.set(currentTarget.x, currentTarget.y, currentTarget.z - dist); break;
            case '右視圖': camera.position.set(currentTarget.x + dist, currentTarget.y, currentTarget.z); break;
            case '左視圖': camera.position.set(currentTarget.x - dist, currentTarget.y, currentTarget.z); break;
        }
        ctrl.update();
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3 | [number, number, number]; type?: SnapType }> = ({ text, position, type }) => {
  const pos = Array.isArray(position) ? position : [position.x, 0.5, position.z];
  let bgColor = "bg-black/80";
  let ringColor = "border-white/20";
  if (type === 'vertex') { bgColor = "bg-green-600/90"; ringColor = "border-green-400"; }
  else if (type === 'midpoint') { bgColor = "bg-cyan-600/90"; ringColor = "border-cyan-400"; }
  else if (type === 'edge') { bgColor = "bg-red-600/90"; ringColor = "border-red-400"; }
  else if (type === 'align') { bgColor = "bg-purple-600/90"; ringColor = "border-purple-400"; }
  return (
    <Html position={[pos[0], 0.5, pos[2]]} center style={{ pointerEvents: 'none' }}>
      <div className={`${bgColor} text-white text-xs px-2 py-1 rounded-md whitespace-nowrap backdrop-blur-sm border ${ringColor} shadow-lg font-bold flex items-center gap-1 transition-all`}>
        {text}
      </div>
    </Html>
  );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType }> = ({ position, type }) => {
    if (type === 'none' || type === 'grid') return null;
    const color = type === 'vertex' ? '#22c55e' : type === 'midpoint' ? '#06b6d4' : type === 'edge' ? '#ef4444' : '#a855f7';
    const rotationZ = type === 'midpoint' ? Math.PI / 4 : 0;
    return (
        <group position={position}>
             <mesh rotation={[-Math.PI/2, 0, rotationZ]}>
                {type === 'vertex' && <circleGeometry args={[0.08, 32]} />}
                {(type === 'midpoint' || type === 'edge') && <planeGeometry args={[0.12, 0.12]} />}
                {type === 'align' && <ringGeometry args={[0.08, 0.12, 4]} />}
                <meshBasicMaterial color={color} depthTest={false} />
            </mesh>
            {(type === 'vertex' || type === 'midpoint' || type === 'edge') && (
                 <mesh rotation={[-Math.PI/2, 0, rotationZ]}>
                    <ringGeometry args={[0.13, 0.15, 32]} />
                    <meshBasicMaterial color={color} transparent opacity={0.5} depthTest={false} />
                </mesh>
            )}
        </group>
    );
}

const PreviewFill: React.FC<{ points: IPoint[], y: number }> = ({ points, y }) => {
  const shape = useMemo(() => {
    if (!points || points.length < 3) return null;
    const s = new THREE.Shape();
    if (points[0]) {
      s.moveTo(points[0].x, -points[0].z);
      for (let i = 1; i < points.length; i++) {
        if (points[i]) s.lineTo(points[i].x, -points[i].z);
      }
    }
    s.closePath();
    return s;
  }, [points]);
  if (!shape) return null;
  return (
    <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, y + 0.02, 0]}>
      <shapeGeometry args={[shape]} />
      <meshBasicMaterial color="#38bdf8" transparent opacity={0.3} side={THREE.DoubleSide} depthTest={false} />
    </mesh>
  );
};

const DrawingManager: React.FC = () => {
  const { tool, addShape, replaceShapes, formatValue, shapes, wallThickness } = useApp();
  const [startPoint, setStartPoint] = useState<IPoint | null>(null);
  const [currentPoint, setCurrentPoint] = useState<IPoint | null>(null);
  const [polyPoints, setPolyPoints] = useState<IPoint[]>([]);
  const [measureStart, setMeasureStart] = useState<IPoint | null>(null);
  const [measureEnd, setMeasureEnd] = useState<IPoint | null>(null);

  // Continuous Drawing Session (for Line tool)
  const drawSession = useRef<{
    active: boolean;
    startPoint: IPoint;
    startSnapShapeId: string | null;
    points: IPoint[]; // Points in the current chain
    generatedIds: string[]; // IDs of the "walls" generated in this session
  }>({ active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] });

  const processingRef = useRef(false);
  const [snapType, setSnapType] = useState<SnapType>('none');
  const [snapObjectId, setSnapObjectId] = useState<string | null>(null);
  const [guides, setGuides] = useState<THREE.Vector3[][]>([]);

  const { raycaster, scene, camera } = useThree();

  useEffect(() => {
    setStartPoint(null);
    setCurrentPoint(null);
    setPolyPoints([]);
    setMeasureStart(null);
    setMeasureEnd(null);
    setSnapType('none');
    setGuides([]);
    processingRef.current = false;
    drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
  }, [tool]);

  // Handle Cancel (Esc)
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape') {
              if (drawSession.current.active) {
                  drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
                  setStartPoint(null);
              }
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  useFrame(({ pointer }) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
        if (currentPoint) setCurrentPoint(null);
        return;
    }

    raycaster.setFromCamera(pointer, camera);
    const interactables = scene.children.filter(obj => 
        obj.name === 'ground_plane'
    );
    const intersects = raycaster.intersectObjects(interactables, true);

    if (intersects.length > 0) {
        const rawPoint = intersects[0].point;

        // Active points for snapping
        const activeSnapPoints = [...polyPoints];
        if (startPoint) activeSnapPoints.push(startPoint);
        if (drawSession.current.active && drawSession.current.points.length > 0) {
            // Add start of current chain to allow closing loop
            activeSnapPoints.push(drawSession.current.points[0]);
        }

        const snapResult = getGeometrySnap(rawPoint, shapes, activeSnapPoints, SNAP_THRESHOLD);

        const x = snapResult.position.x;
        const z = snapResult.position.z;
        let y = snapResult.position.y;
        if (y < 0.05) y = 0;

        if (!currentPoint || 
            Math.abs(currentPoint.x - x) > 0.001 || 
            Math.abs(currentPoint.z - z) > 0.001 ||
            snapType !== snapResult.type) {

            setCurrentPoint({ x, y, z });
            setSnapType(snapResult.type);
            setSnapObjectId(snapResult.snapObjectId || null);
            setGuides(snapResult.guides || []);
        }
    } else {
        if (currentPoint) {
            setCurrentPoint(null);
            setSnapType('none');
            setSnapObjectId(null);
            setGuides([]);
        }
    }
  });

  const handleClick = (e: ThreeEvent<MouseEvent>) => {
    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL || !currentPoint) return;
    e.stopPropagation(); 
    if (processingRef.current) return;

    const p = { ...currentPoint };

    // --- MEASURE TOOL ---
    if (tool === ToolType.MEASURE) {
        if (!measureStart) {
            setMeasureStart(p);
            setMeasureEnd(null);
        } else {
            const dist = Math.sqrt(Math.pow(p.x - measureStart.x, 2) + Math.pow(p.z - measureStart.z, 2));
            if (dist > 0.01) {
                addShape({
                    id: `dim-${Date.now()}`,
                    name: '尺寸標註',
                    type: 'dimension',
                    points: [measureStart, p], 
                    height: 0,
                    color: DIMENSION_COLOR,
                    position: [0, 0, 0],
                    rotation: 0,
                    scale: [1, 1, 1]
                });
            }
            setMeasureStart(null);
            setMeasureEnd(null);
        }
        return;
    }

    // --- POLYGON TOOL ---
    if (tool === ToolType.DRAW_POLY) {
      if (polyPoints.length > 2) {
         const start = polyPoints[0];
         const dist = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));
         if (dist < SNAP_THRESHOLD) { 
           // Close loop explicitly
           createPolygonShape(polyPoints);
           setPolyPoints([]);
           return;
         }
      }
      setPolyPoints([...polyPoints, p]);
      return;
    } 

    // --- LINE / RECT / CIRCLE / ARC TOOLS ---
    if (!startPoint) {
        setStartPoint(p);
        if (tool === ToolType.DRAW_LINE) {
            // Start Continuous Session
            drawSession.current = {
                active: true,
                startPoint: p,
                startSnapShapeId: snapObjectId || null,
                points: [p],
                generatedIds: []
            };
        }
    } else {
        // We have a start point, and user clicked 'p'
        // Check for loop closing first if drawing lines
        if (tool === ToolType.DRAW_LINE && drawSession.current.active) {
            const start = drawSession.current.points[0];
            const distToStart = Math.sqrt(Math.pow(p.x - start.x, 2) + Math.pow(p.z - start.z, 2));

            // IF CLOSE TO START POINT -> CLOSE LOOP
            if (distToStart < SNAP_THRESHOLD && drawSession.current.points.length > 2) {
                const polyPts = [...drawSession.current.points]; // All points accumulated so far

                // 1. Create the single polygon shape
                const newPoly = createPolygonShapeObject(polyPts);

                // 2. Remove all the temporary walls we just drew
                replaceShapes(drawSession.current.generatedIds, [newPoly]);

                // 3. Reset session
                drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
                setStartPoint(null);
                return;
            }
        }

        const dist = Math.sqrt(Math.pow(p.x - startPoint.x, 2) + Math.pow(p.z - startPoint.z, 2));
        if (dist > 0.01) {
             finishPrimitive(startPoint, p);
        }
    }
  };

  // Helper to create the object but not add it yet (for replaceShapes)
  const createPolygonShapeObject = (pts: IPoint[]): IShape => {
    // Center logic
    const cx = pts.reduce((sum, p) => sum + p.x, 0) / pts.length;
    const cz = pts.reduce((sum, p) => sum + p.z, 0) / pts.length;
    const cy = pts[0].y;

    // Local coords
    const centeredPoints = pts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
    centeredPoints.push(centeredPoints[0]); // Close explicitly for Three.js Shape

    return {
      id: `poly-${Date.now()}`,
      name: `多邊形`,
      type: 'flat', // Start as flat
      points: centeredPoints,
      height: DEFAULT_HEIGHT, // Very thin to sit on floor
      color: FLAT_COLOR,
      position: [cx, cy, cz],
      rotation: 0,
      scale: [1, 1, 1]
    };
  };

  const createPolygonShape = (pts: IPoint[]) => {
      const shape = createPolygonShapeObject(pts);
      addShape(shape);
  };

  const finishPrimitive = (start: IPoint, end: IPoint) => {
    if (processingRef.current) return;
    processingRef.current = true;

    // ... (Primitive Generation Logic) ...
    let points: IPoint[] = [];
    let name = "平面";
    const cx = (start.x + end.x) / 2;
    const cz = (start.z + end.z) / 2;
    const dx = end.x - start.x;
    const dz = end.z - start.z;
    const dist = Math.sqrt(dx*dx + dz*dz);
    let finalPos: [number, number, number] = [0,0,0];

    switch (tool) {
      case ToolType.DRAW_LINE:
        const thickness = wallThickness; 
        const len = dist;
        points = [
          { x: 0, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: -thickness/2 },
          { x: len, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: thickness/2 },
          { x: 0, y: 0, z: -thickness/2 }
        ];
        finalPos = [start.x, start.y, start.z]; 
        name = "牆面";
        break;
      case ToolType.DRAW_RECT:
        const w = Math.abs(dx);
        const d = Math.abs(dz);
        finalPos = [cx, start.y, cz];
        points = [
            { x: -w/2, y: 0, z: -d/2 },
            { x: w/2, y: 0, z: -d/2 },
            { x: w/2, y: 0, z: d/2 },
            { x: -w/2, y: 0, z: d/2 },
            { x: -w/2, y: 0, z: -d/2 }
        ];
        name = "區域";
        break;
      case ToolType.DRAW_CIRCLE:
        finalPos = [start.x, start.y, start.z];
        points = createCirclePoints(dist);
        name = "圓形";
        break;
      case ToolType.DRAW_ARC:
        finalPos = [start.x, start.y, start.z];
        points = createArcPoints(dist);
        name = "開門";
        break;
    }

    let rotation = 0;
    if (tool === ToolType.DRAW_LINE || tool === ToolType.DRAW_ARC) {
       rotation = -Math.atan2(dz, dx); 
    }

    const newShapeId = `shape-${Date.now()}-${Math.floor(Math.random()*1000)}`;

    // For Rectangle, Circle - immediately create a flat polygon (surface)
    // For Line - create a "Wall" (thick line) unless it closes a loop (handled in handleClick)
    const isSurface = tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_POLY;

    const newShape: IShape = {
      id: newShapeId,
      name: isSurface ? "多邊形" : `${name}`,
      type: isSurface ? 'flat' : 'flat', // All start flat, but lines have thickness
      points,
      height: DEFAULT_HEIGHT,
      color: isSurface ? FLAT_COLOR : DEFAULT_COLOR,
      position: finalPos,
      rotation: rotation,
      scale: [1, 1, 1]
    };

    // Update session tracking
    if (tool === ToolType.DRAW_LINE && drawSession.current.active) {
        drawSession.current.points.push(end);
        drawSession.current.generatedIds.push(newShapeId);
    }

    const idsToRemove: string[] = [];
    const newShapesToAdd: IShape[] = [newShape];
    let sessionReset = false;

    // --- LOGIC A: Polyline Cut (Splitting a shape by a chain of lines) ---
    // Only applies if we are drawing lines across an existing shape
    if (tool === ToolType.DRAW_LINE && drawSession.current.active) {
        const session = drawSession.current;
        const startSnapId = session.startSnapShapeId;
        const endSnapId = snapObjectId;

        if (startSnapId && endSnapId && startSnapId === endSnapId && session.points.length >= 2) {
             const targetShape = shapes.find(s => s.id === startSnapId);
             if (targetShape && targetShape.type !== 'dimension') {
                 const worldShapePoints = targetShape.points.map(p => transformPoint(p, targetShape));
                 const splitResult = splitShapeByPolyline({ ...targetShape, points: worldShapePoints }, session.points);

                 if (splitResult) {
                     idsToRemove.push(targetShape.id);
                     idsToRemove.push(...session.generatedIds); // Remove lines
                     newShapesToAdd.length = 0;
                     newShapesToAdd.push(...splitResult);
                     sessionReset = true;
                 }
             }
        }
    }

    // 3. Batch Update
    if (idsToRemove.length > 0) {
        replaceShapes(idsToRemove, newShapesToAdd);
    } else {
        addShape(newShape);
    }

    // Handle Continuous Drawing State
    if (tool === ToolType.DRAW_LINE && !sessionReset) {
        setStartPoint(end); // Continue drawing from end point
    } else {
        setStartPoint(null);
        if (tool === ToolType.DRAW_LINE) {
             drawSession.current = { active: false, startPoint: {x:0,y:0,z:0}, startSnapShapeId: null, points: [], generatedIds: [] };
        }
    }

    setTimeout(() => { processingRef.current = false; }, 100);
  };

  const previewPoints = useMemo(() => {
     if (tool === ToolType.DRAW_POLY) {
        if (polyPoints.length === 0 && !currentPoint) return [];
        const pts = [...polyPoints];
        if (currentPoint) pts.push(currentPoint);
        return pts;
     }

     if (startPoint && currentPoint) {
         if (tool === ToolType.DRAW_LINE) {
             // Visual hint for closing loop
             if (drawSession.current.active && drawSession.current.points.length > 2) {
                 const start = drawSession.current.points[0];
                 const distToStart = Math.sqrt((currentPoint.x - start.x)**2 + (currentPoint.z - start.z)**2);
                 if (distToStart < SNAP_THRESHOLD) {
                     // Show polygon preview!
                     const loopPoints = [...drawSession.current.points, start];
                     return loopPoints; 
                 }
             }

             const thickness = wallThickness; 
             const dx = currentPoint.x - startPoint.x;
             const dz = currentPoint.z - startPoint.z;
             const len = Math.sqrt(dx*dx + dz*dz);
             if (len < 0.01) return [startPoint, currentPoint];
             const nx = -dz / len;
             const nz = dx / len;
             const ox = nx * (thickness / 2);
             const oz = nz * (thickness / 2);
             return [
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
               { x: currentPoint.x + ox, y: 0, z: currentPoint.z + oz },
               { x: currentPoint.x - ox, y: 0, z: currentPoint.z - oz },
               { x: startPoint.x - ox, y: 0, z: startPoint.z - oz },
               { x: startPoint.x + ox, y: 0, z: startPoint.z + oz },
             ];
         }
         if (tool === ToolType.DRAW_RECT) {
             return [
                 startPoint,
                 { x: currentPoint.x, y: 0, z: startPoint.z },
                 currentPoint,
                 { x: startPoint.x, y: 0, z: currentPoint.z },
                 startPoint
             ];
         }
         if (tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
             const dist = Math.sqrt(Math.pow(currentPoint.x - startPoint.x, 2) + Math.pow(currentPoint.z - startPoint.z, 2));
             const func = tool === ToolType.DRAW_CIRCLE ? createCirclePoints : createArcPoints;
             const seg = tool === ToolType.DRAW_CIRCLE ? 64 : 32;
             return func(dist, seg).map(p => ({
                 x: p.x + startPoint.x,
                 y: 0,
                 z: p.z + startPoint.z
             }));
         }
     }
     return [];
  }, [tool, startPoint, currentPoint, polyPoints, wallThickness]);

  const drawY = useMemo(() => {
    if (startPoint) return startPoint.y;
    if (polyPoints.length > 0) return polyPoints[0].y;
    if (currentPoint) return currentPoint.y;
    return 0;
  }, [startPoint, polyPoints, currentPoint]);

  // Determine Tooltip Text
  const getTooltipText = () => {
      // Loop closing hint
      if (tool === ToolType.DRAW_LINE && drawSession.current.active && currentPoint) {
         const start = drawSession.current.points[0];
         const distToStart = Math.sqrt((currentPoint.x - start.x)**2 + (currentPoint.z - start.z)**2);
         if (distToStart < SNAP_THRESHOLD && drawSession.current.points.length > 2) {
             return "封閉形狀";
         }
      }

      if (tool === ToolType.MEASURE && measureStart && currentPoint) {
        const dist = Math.sqrt(
            Math.pow(currentPoint.x - measureStart.x, 2) + 
            Math.pow(currentPoint.z - measureStart.z, 2) +
            Math.pow(currentPoint.y - measureStart.y, 2)
        );
        return `距離: ${formatValue(dist)}`;
      }

      if (snapType === 'vertex') return "端點";
      if (snapType === 'midpoint') return "中點";
      if (snapType === 'edge') return "在邊線上";
      if (snapType === 'align') return "對齊";

      return "";
  };

  const tooltipText = getTooltipText();
  const isClosingLoop = tooltipText === "封閉形狀";

  return (
    <>
      <mesh 
        name="ground_plane"
        rotation={[-Math.PI / 2, 0, 0]} 
        position={[0, -0.01, 0]} 
        onClick={handleClick}
      >
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial color="black" transparent opacity={0} />
      </mesh>

      {/* Main Cursor Ring */}
      {currentPoint && tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && (
        <group position={[currentPoint.x, currentPoint.y + 0.05, currentPoint.z]}>
            {snapType === 'grid' || snapType === 'none' ? (
                <mesh rotation={[-Math.PI / 2, 0, 0]}>
                    <ringGeometry args={[0.1, 0.15, 32]} />
                    <meshBasicMaterial color={isClosingLoop ? "#facc15" : "#ef4444"} depthTest={false} />
                </mesh>
            ) : null}
            <SnapIndicator position={new THREE.Vector3(0,0,0)} type={snapType} />
        </group>
      )}

      {guides.map((pts, i) => (
         <Line 
            key={`guide-${i}`} 
            points={pts.map(p => [p.x, p.y + 0.06, p.z] as [number, number, number])} 
            color="#a855f7" 
            lineWidth={2} 
            dashed 
            dashScale={10} 
            depthTest={false}
         />
      ))}

      {tool === ToolType.MEASURE && measureStart && (
        <>
            <Line 
                points={[
                    [measureStart.x, measureStart.y + 0.05, measureStart.z],
                    (() => {
                        const target = measureEnd || currentPoint || measureStart;
                        return [target.x, target.y + 0.05, target.z] as [number, number, number];
                    })()
                ]} 
                color="#facc15" 
                lineWidth={2} 
                dashed 
                dashScale={50}
                depthTest={false}
            />
             <mesh position={[measureStart.x, measureStart.y, measureStart.z]}>
                <sphereGeometry args={[0.08]} />
                <meshBasicMaterial color="#facc15" depthTest={false} />
            </mesh>
            {(measureEnd || currentPoint) && (
                <mesh position={(() => {
                    const p = measureEnd || currentPoint;
                    return p ? [p.x, p.y, p.z] : [0,0,0];
                })()}>
                    <sphereGeometry args={[0.08]} />
                    <meshBasicMaterial color="#facc15" depthTest={false} />
                </mesh>
            )}
        </>
      )}

      {currentPoint && tooltipText && (
          <CursorTooltip 
            position={[currentPoint.x, currentPoint.y + 0.5, currentPoint.z]}
            text={tooltipText}
            type={snapType}
          />
      )}

      {/* Preview Logic: If closing loop, fill it */}
      {previewPoints.length > 0 && (startPoint || polyPoints.length > 0 || isClosingLoop) && (
         <PreviewFill points={previewPoints} y={drawY} />
      )}

      {previewPoints.length > 1 && (
        <Line 
           name="preview_helper"
           points={previewPoints.map(p => [p.x, drawY + 0.06, p.z] as [number, number, number])}
           color="#38bdf8"
           lineWidth={2}
           transparent
           opacity={0.8}
        />
      )}
    </>
  );
};

const PushPullHandle: React.FC<{
  position: THREE.Vector3;
  rotation: THREE.Euler;
  axis: 'x' | 'y' | 'z';
  color: string;
  onDragStart: () => void;
  onDrag: (e: any) => void;
  onDragEnd: () => void;
  label: string;
}> = ({ position, rotation, axis, color, onDragStart, onDrag, onDragEnd, label }) => {
  return (
    <TransformControls
      mode="translate"
      position={[position.x, position.y, position.z]}
      rotation={[rotation.x, rotation.y, rotation.z]}
      showX={axis === 'x'}
      showY={axis === 'y'}
      showZ={axis === 'z'}
      onMouseDown={onDragStart}
      onObjectChange={onDrag}
      onMouseUp={onDragEnd}
      translationSnap={0.05}
    >
      <mesh>
         <boxGeometry args={[0.2, 0.2, 0.2]} />
         <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.8} />
      </mesh>
      <Html position={[axis === 'x' ? 0.3 : 0, axis === 'y' ? 0.3 : 0, axis === 'z' ? 0.3 : 0]} center style={{ pointerEvents: 'none' }}>
         <div className="text-white text-[10px] px-1 rounded font-mono shadow-md whitespace-nowrap" style={{ backgroundColor: color }}>
             {label}
         </div>
      </Html>
    </TransformControls>
  );
};

const RenderedShape: React.FC<{ shape: IShape }> = ({ shape }) => {
  const { selectedId, setSelectedId, tool, updateShape, formatValue } = useApp();
  const isSelected = selectedId === shape.id;
  const groupRef = useRef<THREE.Group>(null);

  const dragState = useRef<{
     fixedPoint: THREE.Vector3;
     baseSize: number;
     initialScale: number;
     initialPos: THREE.Vector3;
     rotation: number;
     worldDirection: THREE.Vector3;
  } | null>(null);

  const threeShape = useMemo(() => {
    if (shape.type === 'dimension') return null;
    return createThreeShape(shape.points);
  }, [shape.points, shape.type]);

  const baseDimensions = useMemo(() => getBaseDimensions(shape.points), [shape.points]);

  const geometry = useMemo(() => {
    if (!threeShape || shape.type === 'dimension') return null;
    return new THREE.ExtrudeGeometry(threeShape, { depth: shape.height, bevelEnabled: false });
  }, [threeShape, shape.height, shape.type]);

  useEffect(() => {
    if (groupRef.current && !dragState.current) {
        groupRef.current.position.set(shape.position[0], shape.position[1], shape.position[2]);
        groupRef.current.rotation.set(0, shape.rotation, 0); 
        groupRef.current.scale.set(shape.scale[0], shape.scale[1], shape.scale[2]);
    }
  }, [shape.position, shape.rotation, shape.scale]);

  const handleTransformChange = (e: any) => {
      if (!groupRef.current) return;
      updateShape(shape.id, {
        position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
        rotation: groupRef.current.rotation.y,
        scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
      });
  };

  const { maxX, maxZ, width: baseWidth, depth: baseDepth } = baseDimensions;
  const currentW = baseWidth * shape.scale[0];
  const currentD = baseDepth * shape.scale[2];
  const currentH = shape.height * shape.scale[1]; 

  const setupDrag = (face: 'right' | 'left' | 'front' | 'back') => {
      if (!groupRef.current) return;

      const rot = shape.rotation;
      const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
      const right = new THREE.Vector3(1, 0, 0).applyAxisAngle(new THREE.Vector3(0, 1, 0), rot);
      const forward = new THREE.Vector3(0, 0, 1).applyAxisAngle(new THREE.Vector3(0, 1, 0), rot);

      let fixedPoint = pos.clone();
      let worldDirection = right.clone();
      let baseSize = baseWidth;
      let initialScale = shape.scale[0];

      if (face === 'right') {
          fixedPoint.sub(right.clone().multiplyScalar(currentW / 2));
          worldDirection = right;
          baseSize = baseWidth;
          initialScale = shape.scale[0];
      } else if (face === 'left') {
          fixedPoint.add(right.clone().multiplyScalar(currentW / 2));
          worldDirection = right.clone().negate();
          baseSize = baseWidth;
          initialScale = shape.scale[0];
      } else if (face === 'front') {
          fixedPoint.sub(forward.clone().multiplyScalar(currentD / 2));
          worldDirection = forward;
          baseSize = baseDepth;
          initialScale = shape.scale[2];
      } else if (face === 'back') {
          fixedPoint.add(forward.clone().multiplyScalar(currentD / 2));
          worldDirection = forward.clone().negate();
          baseSize = baseDepth;
          initialScale = shape.scale[2];
      }

      dragState.current = {
          fixedPoint,
          worldDirection,
          baseSize,
          initialScale,
          initialPos: pos,
          rotation: rot
      };
  };

  const handleDrag = (e: any, face: 'right' | 'left' | 'front' | 'back') => {
     if (!groupRef.current || !dragState.current || !e.target.object) return;
     const handlePos = e.target.object.position.clone();
     const { fixedPoint, worldDirection, baseSize } = dragState.current;
     const dragVec = handlePos.sub(fixedPoint);
     let newLen = dragVec.dot(worldDirection);
     if (newLen < 0.1) newLen = 0.1;
     const newScale = newLen / baseSize;
     const centerOffset = worldDirection.clone().multiplyScalar(newLen / 2);
     const newCenter = fixedPoint.clone().add(centerOffset);
     groupRef.current.position.copy(newCenter);
     if (face === 'right' || face === 'left') {
         groupRef.current.scale.setX(newScale);
     } else {
         groupRef.current.scale.setZ(newScale);
     }
  };

  const handleDragEnd = () => {
      if (!groupRef.current) return;
      updateShape(shape.id, {
          position: [groupRef.current.position.x, groupRef.current.position.y, groupRef.current.position.z],
          scale: [groupRef.current.scale.x, groupRef.current.scale.y, groupRef.current.scale.z]
      });
      dragState.current = null;
  };

  const onHeightDrag = (e: any) => {
    if (!groupRef.current || !e.target.object) return;
    const currentY = e.target.object.position.y;
    // Allow going very small, but not zero/negative for math safety
    const newScaleY = Math.max(0.001, currentY / shape.height);
    groupRef.current.scale.y = newScaleY;
  };

  const onHeightEnd = (e: any) => {
    if (!groupRef.current || !e.target.object) return;
    const currentY = e.target.object.position.y;
    const newHeight = Math.max(0.01, currentY);

    // Auto-convert to solid if extruded
    const isNowSolid = newHeight > 0.1;
    const newColor = (shape.type === 'flat' && isNowSolid) ? DEFAULT_COLOR : shape.color;

    updateShape(shape.id, { 
       height: newHeight,
       scale: [shape.scale[0], 1, shape.scale[2]], 
       type: isNowSolid ? 'solid' : 'flat',
       color: newColor
    });
    groupRef.current.scale.y = 1;
  };


  if (shape.type === 'dimension') {
      const p1 = shape.points[0];
      const p2 = shape.points[1];
      const dist = Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.z - p1.z, 2) + Math.pow(p2.y - p1.y, 2));
      const midX = (p1.x + p2.x) / 2;
      const midY = (p1.y + p2.y) / 2 + 0.1;
      const midZ = (p1.z + p2.z) / 2;
      return (
        <group 
            ref={groupRef}
            userData={{ isShape: true, id: shape.id }}
            onClick={(e) => {
                if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
                    e.stopPropagation();
                    setSelectedId(shape.id);
                }
            }}
        >
            <Line points={[[p1.x, p1.y+0.05, p1.z], [p2.x, p2.y+0.05, p2.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={3} dashed dashScale={10} />
            <mesh position={[p1.x, p1.y+0.05, p1.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <mesh position={[p2.x, p2.y+0.05, p2.z]}><sphereGeometry args={[0.06]} /><meshBasicMaterial color={isSelected ? HIGHLIGHT_COLOR : shape.color} /></mesh>
            <Html position={[midX, midY, midZ]} center style={{ pointerEvents: 'none' }}>
                <div className={`text-xs px-2 py-1 rounded whitespace-nowrap backdrop-blur-sm border ${isSelected ? 'bg-blue-600/90 text-white border-blue-400' : 'bg-black/70 text-yellow-400 border-yellow-500/50'}`}>
                    {formatValue(dist)}
                </div>
            </Html>
        </group>
      );
  }

  const rot = shape.rotation;
  const sin = Math.sin(rot);
  const cos = Math.cos(rot);
  const cx = shape.position[0];
  const cy = shape.position[1];
  const cz = shape.position[2];

  const hw = currentW / 2;
  const hd = currentD / 2;
  const hh = currentH;

  const posRight = new THREE.Vector3(cx + hw * cos, cy + hh / 2, cz + hw * sin);
  const posLeft = new THREE.Vector3(cx - hw * cos, cy + hh / 2, cz - hw * sin);
  const posFront = new THREE.Vector3(cx - hd * sin, cy + hh / 2, cz + hd * cos);
  const posBack = new THREE.Vector3(cx + hd * sin, cy + hh / 2, cz - hd * cos);
  const posTop = new THREE.Vector3(cx, cy + hh, cz);

  const euler = new THREE.Euler(0, rot, 0);

  return (
    <>
      {isSelected && tool === ToolType.SELECT && (
        <TransformControls
            object={groupRef}
            mode="translate"
            showY={true} showX={true} showZ={true}
            onMouseUp={handleTransformChange}
        />
      )}

      {isSelected && tool === ToolType.PUSH_PULL && (
        <>
            <PushPullHandle position={posTop} rotation={euler} axis="y" color="#4ade80" label="高" onDragStart={() => {}} onDrag={onHeightDrag} onDragEnd={onHeightEnd} />
            {/* Hide side handles if purely flat to avoid confusion, or keep them to allow scale */}
            <PushPullHandle position={posRight} rotation={euler} axis="x" color="#f87171" label="右" onDragStart={() => setupDrag('right')} onDrag={(e) => handleDrag(e, 'right')} onDragEnd={handleDragEnd} />
            <PushPullHandle position={posLeft} rotation={euler} axis="x" color="#f87171" label="左" onDragStart={() => setupDrag('left')} onDrag={(e) => handleDrag(e, 'left')} onDragEnd={handleDragEnd} />
            <PushPullHandle position={posFront} rotation={euler} axis="z" color="#60a5fa" label="前" onDragStart={() => setupDrag('front')} onDrag={(e) => handleDrag(e, 'front')} onDragEnd={handleDragEnd} />
            <PushPullHandle position={posBack} rotation={euler} axis="z" color="#60a5fa" label="後" onDragStart={() => setupDrag('back')} onDrag={(e) => handleDrag(e, 'back')} onDragEnd={handleDragEnd} />
        </>
      )}

      <group 
        ref={groupRef}
        userData={{ isShape: true, id: shape.id }}
        onClick={(e) => {
          if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) {
            e.stopPropagation();
            setSelectedId(shape.id);
          }
        }}
      >
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <primitive object={geometry} attach="geometry" />
            <meshStandardMaterial 
              color={isSelected ? HIGHLIGHT_COLOR : shape.color} 
              transparent={isSelected || shape.type === 'flat'} 
              opacity={shape.type === 'flat' ? 0.6 : (isSelected ? 0.9 : 1)}
              side={THREE.DoubleSide}
            />
            {isSelected && (
              <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="white" />
              </lineSegments>
            )}
        </mesh>
      </group>
    </>
  );
};

