export default Viewport;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, Line, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    guides?: THREE.Vector3[][];
}

// --- Geometry Helpers (Cutting Logic) ---

// Check if point C is on segment AB
const isPointOnSegment = (c: IPoint, a: IPoint, b: IPoint) => {
    const cross = (c.z - a.z) * (b.x - a.x) - (c.x - a.x) * (b.z - a.z);
    if (Math.abs(cross) > EPSILON) return false; // Not collinear

    const dot = (c.x - a.x) * (b.x - a.x) + (c.z - a.z) * (b.z - a.z);
    if (dot < -EPSILON) return false; // Before a

    const squaredLen = (b.x - a.x)**2 + (b.z - a.z)**2;
    if (dot > squaredLen + EPSILON) return false; // After b

    return true;
};

// Find which edge index of the polygon the point lies on
const findEdgeIndex = (poly: IPoint[], p: IPoint): number => {
    for (let i = 0; i < poly.length; i++) {
        const p1 = poly[i];
        const p2 = poly[(i + 1) % poly.length];
        if (isPointOnSegment(p, p1, p2)) return i;
    }
    return -1;
};

// Split a shape by a polyline that starts and ends on the shape's boundary
const splitShapeByPolyline = (shape: IShape, polyline: IPoint[]): IShape[] | null => {
    const poly = shape.points;
    if (polyline.length < 2) return null;

    const startP = polyline[0];
    const endP = polyline[polyline.length - 1];

    const idxA = findEdgeIndex(poly, startP);
    const idxB = findEdgeIndex(poly, endP);

    if (idxA === -1 || idxB === -1) return null;

    // Helper to extract loop
    // Polygon 1: StartP -> ... polyline ... -> EndP -> Shape[idxB+1] ... -> Shape[idxA] -> StartP
    // But we need to be careful with direction and indices.

    // Construct new Polygon 1
    // Follow shape from idxA next to idxB, then connect via reversed polyline
    const newPoly1: IPoint[] = [startP];

    // Add polyline points (excluding start, including end)
    for (let i = 1; i < polyline.length; i++) {
        newPoly1.push(polyline[i]);
    }

    // From EndP (which is polyline[last]), traverse shape boundary until StartP
    // EndP is on edge idxB (between poly[idxB] and poly[idxB+1])
    // So next vertex is poly[idxB+1]
    let curr = (idxB + 1) % poly.length;
    while (curr !== (idxA + 1) % poly.length) {
        newPoly1.push(poly[curr]);
        curr = (curr + 1) % poly.length;
    }
    // Finally close with StartP (implicit or explicit)
    // isPointOnSegment checks if it lies ON the segment.
    // If startP is exactly poly[idxA+1], we might duplicate points, but that's usually fine for rendering.

    // Construct new Polygon 2
    // Follow shape from idxB next to idxA, then connect via polyline
    const newPoly2: IPoint[] = [endP];

    // Add reversed polyline (excluding end, including start)
    for (let i = polyline.length - 2; i >= 0; i--) {
        newPoly2.push(polyline[i]);
    }

    // From StartP, traverse shape boundary until EndP
    // StartP is on edge idxA. Next vertex is poly[idxA+1]
    curr = (idxA + 1) % poly.length;
    while (curr !== (idxB + 1) % poly.length) {
        newPoly2.push(poly[curr]);
        curr = (curr + 1) % poly.length;
    }

    // Helper to center and create shape
    const makeShape = (pts: IPoint[], suffix: string): IShape => {
        // Remove duplicates/close loop
        const uniquePts = pts.filter((p, i) => {
             const next = pts[(i+1)%pts.length];
             return Math.abs(p.x - next.x) > EPSILON || Math.abs(p.z - next.z) > EPSILON;
        });

        if (uniquePts.length < 3) return shape; // Fail safe

        const cx = uniquePts.reduce((s, p) => s + p.x, 0) / uniquePts.length;
        const cz = uniquePts.reduce((s, p) => s + p.z, 0) / uniquePts.length;

        const localPts = uniquePts.map(p => ({ x: p.x - cx, y: 0, z: p.z - cz }));
        localPts.push(localPts[0]); // Ensure closed

        return {
            ...shape,
            id: `${shape.id}-${suffix}`,
            position: [cx, shape.position[1], cz],
            points: localPts,
            rotation: 0, // Reset rotation since points are world-aligned
            scale: [1, 1, 1]
        };
    };

    return [makeShape(newPoly1, 'cut1'), makeShape(newPoly2, 'cut2')];
};

// Calculate Polygon Area (for validation)
const calculatePolygonArea = (points: IPoint[]) => {
    let area = 0;
    for (let i = 0; i < points.length; i++) {
        const j = (i + 1) % points.length;
        area += points[i].x * points[j].z;
        area -= points[i].z * points[j].x;
    }
    return Math.abs(area / 2);
};

// --- Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;

  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) {
            shape.lineTo(points[i].x, -points[i].z);
        }
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const getBaseDimensions = (points: IPoint[]) => {
    if (!points || points.length === 0) return { width: 0, depth: 0, minX: 0, maxX: 0, minZ: 0, maxZ: 0, centerX: 0, centerZ: 0 };
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        minX = Math.min(minX, p.x);
        maxX = Math.max(maxX, p.x);
        minZ = Math.min(minZ, p.z);
        maxZ = Math.max(maxZ, p.z);
    });
    return { 
        width: maxX - minX || 0.1, 
        depth: maxZ - minZ || 0.1,
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2
    };
};

// Transform a local point to world space based on shape props
const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);

    // Scale
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;

    // Rotate (around Y axis)
    // x' = x*cos - z*sin
    // z' = x*sin + z*cos
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;

    // Translate
    return new THREE.Vector3(
        xRot + shape.position[0],
        shape.position[1], 
        zRot + shape.position[2]
    );
};

// Project point onto line segment [v, w]
const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const l2 = v.distanceToSquared(w);
  if (l2 === 0) return v;
  let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(
    v.x + t * (w.x - v.x),
    v.y, // Keep height consistent for now
    v.z + t * (w.z - v.z)
  );
};

// --- Geometry Snapping Logic (Adsorption & Alignment) ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y,
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    // 0. Check Active Points (Priority: High)
    if (activePoints && activePoints.length > 0) {
        for (const p of activePoints) {
             const pt = new THREE.Vector3(p.x, p.y, p.z);
             const dist = pt.distanceTo(cursorPos);
             if (dist < threshold && dist < bestSnap.distance) {
                 bestSnap = {
                     position: pt,
                     type: 'vertex',
                     distance: dist
                 };
             }
        }
    }

    // 1. Check Existing Shapes Vertices (Priority: High)
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            const dist = worldPt.distanceTo(cursorPos);

            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = {
                    position: worldPt,
                    type: 'vertex',
                    distance: dist,
                    snapObjectId: shape.id
                };
            }
        }
    }

    if (bestSnap.type === 'vertex') return bestSnap;

    // 2. Check Edges & Midpoints (Priority: Medium)
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;

    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;

        const pts = shape.points;
        const len = pts.length;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);

             // Midpoint check
             const mid = new THREE.Vector3().addVectors(p1, p2).multiplyScalar(0.5);
             const distMid = mid.distanceTo(cursorPos);

             if (distMid < threshold && distMid < minEdgeDist) {
                 bestEdgeSnap = {
                     position: mid,
                     type: 'midpoint',
                     distance: distMid,
                     snapObjectId: shape.id
                 };
                 minEdgeDist = distMid;
                 continue; // Found a midpoint closer than edge, optimize
             }

             // Edge Projection check (Fitting against the edge)
             const projected = closestPointOnSegment(cursorPos, p1, p2);
             const distEdge = projected.distanceTo(cursorPos);

             if (distEdge < threshold && distEdge < minEdgeDist) {
                 bestEdgeSnap = {
                     position: projected,
                     type: 'edge',
                     distance: distEdge,
                     snapObjectId: shape.id
                 };
                 minEdgeDist = distEdge;
             }
        }
    }

    if (bestEdgeSnap) return bestEdgeSnap;

    // 3. Smart Alignment Guides (Priority: Low)
    let alignX: number | null = null;
    let alignZ: number | null = null;
    let minDiffX = ALIGN_THRESHOLD;
    let minDiffZ = ALIGN_THRESHOLD;
    let guideXSrc: THREE.Vector3 | null = null;
    let guideZSrc: THREE.Vector3 | null = null;

    const candidates: THREE.Vector3[] = [];
    shapes.forEach(s => {
       if(s.type === 'dimension') return;
       s.points.forEach(p => candidates.push(transformPoint(p, s)));
    });
    activePoints.forEach(p => candidates.push(new THREE.Vector3(p.x, p.y, p.z)));

    for (const pt of candidates) {
        const diffX = Math.abs(pt.x - cursorPos.x);
        if (diffX < minDiffX) {
            minDiffX = diffX;
            alignX = pt.x;
            guideXSrc = pt;
        }
        const diffZ = Math.abs(pt.z - cursorPos.z);
        if (diffZ < minDiffZ) {
            minDiffZ = diffZ;
            alignZ = pt.z;
            guideZSrc = pt;
        }
    }

    if (alignX !== null || alignZ !== null) {
        const snappedPos = bestSnap.position.clone();
        if (alignX !== null) snappedPos.x = alignX;
        if (alignZ !== null) snappedPos.z = alignZ;

        const guides: THREE.Vector3[][] = [];
        if (alignX !== null && guideXSrc) {
            guides.push([guideXSrc, new THREE.Vector3(alignX, cursorPos.y, snappedPos.z)]);
        }
        if (alignZ !== null && guideZSrc) {
            guides.push([guideZSrc, new THREE.Vector3(snappedPos.x, cursorPos.y, alignZ)]);
        }

        return {
            position: snappedPos,
            type: 'align',
            distance: 0,
            guides
        };
    }

    return bestSnap;
};

